class Solution:
    def maxProfit(self, workers, tasks):
        avail = set(workers)
        tasks.sort(key=lambda t: -t[1])
        total = 0
        best_left = 0
        for s, p in tasks:
            if s in avail:
                total += p
                avail.remove(s)
            elif p > best_left:
                best_left = p
        return total + best_left

c.cpp:
class Solution {
public:
    long long maxProfit(vector<int>& workers, vector<vector<int>>& tasks) {
        unordered_set<int> avail(workers.begin(), workers.end());
        sort(tasks.begin(), tasks.end(), [](auto& a, auto& b) { return a[1] > b[1]; });
        long long total = 0;
        int bestLeft = 0;
        for (auto& t : tasks) {
            if (avail.count(t[0])) { total += t[1]; avail.erase(t[0]); }
            else bestLeft = max(bestLeft, t[1]);
        }
        return total + bestLeft;
    }
};

c.java:
class Solution {
    public long maxProfit(int[] workers, int[][] tasks) {
        Set<Integer> avail = new HashSet<>();
        for (int w : workers) avail.add(w);
        Arrays.sort(tasks, (a, b) -> Integer.compare(b[1], a[1]));
        long total = 0;
        int bestLeft = 0;
        for (int[] t : tasks) {
            if (avail.contains(t[0])) { total += t[1]; avail.remove(t[0]); }
            else bestLeft = Math.max(bestLeft, t[1]);
        }
        return total + bestLeft;
    }
}

