var maxProfit = function(workers, tasks) {
    const avail = new Set(workers);
    tasks.sort((a, b) => b[1] - a[1]);
    let total = 0, bestLeft = 0;
    for (const [s, p] of tasks) {
        if (avail.has(s)) { total += p; avail.delete(s); }
        else if (p > bestLeft) bestLeft = p;
    }
    return total + bestLeft;
};
